// Generated by Skyramp — UI test for the field-reorder save confirmation.
//
// Scenario: field-reorder-toast-and-persistence  (category: business_rule)
//
// This PR adds notify({ title: t('field_order_saved'), type: 'success' }) to setSort()
// in fields-management.vue. A confirmation is only meaningful if the order it confirms
// actually persisted, so this test asserts both halves: the toast appears after the
// drag, and a full page reload shows the new order served by the API.
import { test } from '@skyramp/skyramp';
import { expect } from '@playwright/test';
import {
	login,
	createCollection,
	dragField,
	fieldOrder,
	reloadDataModelPage,
	sortByField,
} from './skyramp_field_reorder_helpers';

const baseUrl = process.env.SKYRAMP_TEST_BASE_URL || 'http://localhost:8055';

test('reordering fields confirms the save and persists the new order', async ({ page }) => {
	test.setTimeout(180000);
	page.setDefaultTimeout(15000);

	await login(page, baseUrl);
	const collection = await createCollection(page, baseUrl, 'qa_reorder_ok');

	expect(await fieldOrder(page)).toEqual(['id', 'status', 'date_created']);

	// Drag `status` above `id`.
	const saved = page.waitForResponse(
		(r) => r.url().includes(`/fields/${collection}`) && r.request().method() === 'PATCH',
	);
	await dragField(page, 1, 0);
	const response = await saved;
	expect(response.status()).toBe(200);

	// setSort sends `sort: index + 1` for every field in the new visual order; the
	// response echoes what was persisted. Assert the exact values, keyed by field name
	// so the assertion does not depend on the array ordering of the response.
	expect(sortByField(await response.json())).toEqual({ status: 1, id: 2, date_created: 3 });

	// The success confirmation added by this PR.
	await expect(page.getByText('Field order saved')).toBeVisible();

	// The list reflects the new order immediately.
	expect(await fieldOrder(page)).toEqual(['status', 'id', 'date_created']);

	// The confirmation must reflect persisted state, not just local state:
	// reload and re-read the order from the API.
	await reloadDataModelPage(page, baseUrl, collection);
	expect(await fieldOrder(page)).toEqual(['status', 'id', 'date_created']);
});
